//! Runtime for clients generated by `branchline-build`.
//!
//! A generated client is a resource chain that follows the OpenAPI path tree: every path segment is a node, a path
//! parameter is a node that takes a value, and every HTTP method on a path is an async method on its node.
//!
//! ```ignore
//! let notices = api.contests().id(7).notices().get().await?;
//! ```
//!
//! Nodes wrap a [`Route`], which builds the relative path and hands the request to your [`Transport`]. The transport
//! owns everything outside the contract: base URL, authentication and signing, retries, and mapping non-2xx responses
//! to your error type.
//!
//! # Features
//!
//! - `bon` (default): builders for generated types. Turn off together with `Generator::builders(false)`.
//! - `reqwest`: [`Http`], a transport that sends JSON requests to a base URL.
//! - `sigv4`: [`SigV4`], `Http` plus AWS SigV4 signing for IAM-authenticated endpoints such as Lambda Function URLs.

pub use error::Error;
#[cfg(feature = "reqwest")]
pub use failure::HttpError;
pub use http;
#[cfg(feature = "reqwest")]
pub use plain::Http;
pub use route::Route;
#[cfg(feature = "sigv4")]
pub use sigv4::SigV4;
pub use transport::Transport;

/// Used by generated builders (`branchline-build`'s `Generator::builders`).
#[cfg(feature = "bon")]
#[doc(hidden)]
pub use bon;

mod error;
#[cfg(feature = "reqwest")]
mod failure;
mod path;
#[cfg(feature = "reqwest")]
mod plain;
#[cfg(feature = "reqwest")]
mod request;
mod route;
#[cfg(feature = "sigv4")]
mod sigv4;
mod transport;
